/* @autogenerated */
import { normalizeHeader } from 'app/shared/toolkit/entity-import/column-match';
import { SnippetRepository } from 'app/features/template/snippet/repository/snippet-repository.service';
import { take, map } from 'rxjs';
import { BaseImportAction } from 'app/shared/toolkit/action/base-import-action';
import { SnippetAsset } from 'app/features/template/snippet-asset/model/snippet-asset.model';
import { ImportDefinition } from 'app/shared/toolkit/entity-import/entity-import.model';
import { SnippetAssetRepository } from 'app/features/template/snippet-asset/repository/snippet-asset-repository.service';
import { Component, inject } from '@angular/core';
import {
  SNIPPET_ASSET_EXCEL_SENSITIVE,
  SNIPPET_ASSET_EXCEL_COLUMNS,
} from 'app/features/template/snippet-asset/model/snippet-asset-excel-columns';

/** Candidatos que pide cada búsqueda: el filtro puede no ser exacto y se comprueba aquí. */
const LOOKUP_LIMIT = 50;

@Component({
  selector: 'snippet-asset-view-import-action',
  standalone: false,
  templateUrl: './snippet-asset-view-import-action.component.html',
})
export class SnippetAssetViewImportActionComponent extends BaseImportAction<SnippetAsset> {
  protected readonly scope = 'template/snippet-asset';
  protected readonly repository = inject(SnippetAssetRepository);
  private readonly snippetRepository = inject(SnippetRepository);

  readonly definition: ImportDefinition<SnippetAsset> = {
    storageKey: 'template.snippet-asset',
    scope: this.scope,
    // Clave natural (índice único del modelo): una fila con los mismos valores actualiza el elemento
    keys: ['code', 'snippet'],
    columns: SNIPPET_ASSET_EXCEL_COLUMNS,
    sensitive: SNIPPET_ASSET_EXCEL_SENSITIVE,
    // Campos que el backend solo cambia con sus acciones: se aplican tras crear o actualizar
    actions: {
      enabled: [
        { name: 'enable', value: true, run: (item) => this.repository.enable(item.uid) },
        { name: 'disable', value: false, run: (item) => this.repository.disable(item.uid) },
      ],
    },
    references: {
      snippet: {
        resolve: (text) =>
          this.snippetRepository.values({ search: text, limit: LOOKUP_LIMIT }).pipe(
            take(1),
            map((found) => {
              const wanted = normalizeHeader(text);
              const one = found.find(
                (candidate) => candidate.uid === text || normalizeHeader(candidate.code) === wanted,
              );
              return one ? { $ref: one.uid } : null;
            }),
          ),
      },
    },
    defaults: () => ({ enabled: true }),
    display: (values) => String(values.code ?? ''),
    target: {
      acl: () => this.repository.checkAcl(),
      find: (values) =>
        this.repository
          .values({
            code: values.code,
            snippet: values.snippet?.$ref ? [values.snippet.$ref] : undefined,
            limit: LOOKUP_LIMIT,
          })
          .pipe(
            take(1),
            map((found) =>
              found.filter(
                (item) =>
                  item.code === values.code && (!values.snippet?.$ref || item.snippet?.$ref === values.snippet.$ref),
              ),
            ),
          ),
      add: (item) => this.repository.add(item),
      update: (item) => this.repository.update(item),
    },
  };
}
